param([string]$GameRoot=(Join-Path $PSScriptRoot '..\Street Legal Racing - Redline'),[string]$Exe=(Join-Path $PSScriptRoot '..\build\Release\slrr_host.exe'))
$ErrorActionPreference='Stop'; Add-Type @'
using System; using System.Runtime.InteropServices; using System.Text;
public static class KeyProbe { [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h); [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h,uint m,UIntPtr w,IntPtr l); [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc p,IntPtr l); [DllImport("user32.dll")] static extern void GetWindowThreadProcessId(IntPtr h,out uint p); [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern int GetWindowText(IntPtr h,StringBuilder s,int n); delegate bool EnumProc(IntPtr h,IntPtr l); public static IntPtr Find(uint pid){IntPtr x=IntPtr.Zero;EnumWindows((h,l)=>{uint p;GetWindowThreadProcessId(h,out p);var s=new StringBuilder(100);GetWindowText(h,s,100);if(p==pid&&s.ToString().StartsWith("OpenSLRR")){x=h;return false;}return true;},IntPtr.Zero);return x;} public static void Key(IntPtr h,char c,bool up){ushort scan=(ushort)(c=='W'?0x11:c=='S'?0x1f:c=='A'?0x1e:c=='D'?0x20:c=='E'?0x12:c=='N'?0x31:c=='H'?0x23:c=='P'?0x19:c=='Q'?0x10:0);uint m=up?0x101u:0x100u;long lp=((long)scan<<16)|(up?0xc0000000L:0);PostMessage(h,m,(UIntPtr)c,(IntPtr)lp);} }
'@
$root=(Resolve-Path $GameRoot).Path;$exe=(Resolve-Path $Exe).Path;$stamp=Get-Date -Format yyyyMMdd-HHmmss;$out="$(Resolve-Path (Join-Path $PSScriptRoot '..\build'))\key-batch-$stamp.out.log";$err=$out.Replace('.out.log','.err.log');$p=Start-Process $exe -WorkingDirectory (Split-Path $exe) -ArgumentList "--game --window --no-vsync --root `"$root`" --spawn-car cars/racers/Baiern.rpk:0x6 --auto-city --renderer vulkan" -RedirectStandardOutput $out -RedirectStandardError $err -PassThru;Start-Sleep 18;$h=[KeyProbe]::Find($p.Id);if($h -eq 0){throw 'window not found'};[KeyProbe]::SetForegroundWindow($h)|Out-Null;foreach($c in 'W','S','A','D','E','N','H','P','Q'){[KeyProbe]::Key($h,$c,$false);Start-Sleep -Milliseconds 180;[KeyProbe]::Key($h,$c,$true);Start-Sleep -Milliseconds 180};Start-Sleep 2;if(!$p.HasExited){$p.Kill()};$p.WaitForExit();[pscustomobject]@{Out=$out;Err=$err;Keys='W S A D E N H P Q'}|Format-List
